            nonbg=[c for c in range(w) if g[r][c]!=b]
            if nonbg:
                # slide each cell right until hitting another cell or edge; process right-to-left so left cells can land behind
                end=max(nonbg)+1
                for c in sorted(nonbg)[-1::-1]:
                    k=c+1
                    while k<w and g[r][k]==b: k+=1
                    if k<w: new[r][k]=g[r][c]
                # empty original positions
                for c in range(w):
                    v=g[r][c]
                    if v!=b:
                        # removed from new? no—cells move to their landing spot; source becomes bg unless someone lands there
                        pass
                    else:
                        continue
                for c in nonbg:
                    new[r][c]=b
            else: continue
        new=[[b]*w for _ in range(h)]
        for r in range(h):
            for c in range(w):
                nc=[cc for cc in range(c, w) if g[r][cc]!=b]
                if nc:
                    l=min(cc for cc in nc if cc>=c+1)  # nearest to the right
                    if (g[r][l] != b and c < l):
                        new[r][l]=g[r][c]
        for r in range(h):
            for c in range(w):
                if new[r][c]==b: new[r][c]=b
            break
        return None

